// Définitions courtes pour la fiche du cycliste. Les chiffres viennent du profil actif.
import {voyages,VOYAGE_POINTS} from './voyages.js';
import {LEVELS} from './immersion.js';
import {ULTRA_BIKES,ULTRA_GEAR,ULTRA_RACE,ULTRA_HOURS,ULTRA_STEP_MAX,ULTRA_WEIGHT,ULTRA_FERRY_MAX,ULTRA_FERRY_HOURS,ULTRA_SLEEP,ULTRA_RIVALS} from './ultra.js';

export const WIKI_CATEGORIES=[
 {id:'jouer',label:'Jouer'},
 {id:'terrain',label:'Terrains et carte'},
 {id:'vie',label:'Vie du cycliste'},
 {id:'voyage',label:'Voyages et points'},
 {id:'catalogue',label:'Cartes Voyage · hors Ultra'},
 {id:'materiel',label:'Vélos, matériel et pièces'},
 {id:'modes',label:'Modes et événements'},
 {id:'garage-ultra',label:'Garage Ultra'},
 {id:'outils',label:'Outils du jeu'}
];

const amount=(n,one,many)=>`${n} ${n>1?many:one}`;
function voyageObjectives(v){return [
 v.cities&&amount(v.cities,'ville intermédiaire','villes intermédiaires'),
 v.mountainRun&&amount(v.mountainRun,'montagne consécutive','montagnes consécutives'),
 v.coast&&amount(v.coast,'case côtière','cases côtières'),
 v.coastRun&&amount(v.coastRun,'côte consécutive','côtes consécutives'),
 v.plain&&amount(v.plain,'case de plaine','cases de plaine'),
 v.plainRun&&amount(v.plainRun,'plaine consécutive','plaines consécutives'),
 v.mountain&&amount(v.mountain,'case de montagne','cases de montagne'),
 v.chains&&amount(v.chains,'chaîne distincte de 2 montagnes','chaînes distinctes de 2 montagnes'),
 v.hills&&amount(v.hills,'case de moyenne montagne','cases de moyenne montagne'),
 v.cols&&amount(v.cols,'col mythique','cols mythiques')
 ].filter(Boolean).join(' ; ');}

export function wikiEntries(r,{boardMode='plateau'}={}){
 const terrain=(id,name,icon,body,short=`${r.terrain[id]} énergie de base par case`)=>({id,name,icon,category:'terrain',short,body});
 const plateau=boardMode==='plateau',immersion=Boolean(plateau&&r.immersion?.enabled),ultra=Boolean(immersion&&r.immersion?.ultra);
 const victory=r.victory.mode==='multi'?[r.victory.points&&`${r.victory.points} points d’aventure`,r.victory.voyages&&`${r.victory.voyages} voyages réussis`,r.victory.days&&`${r.victory.days} jours`].filter(Boolean).join(' ou '):r.victory.mode==='points'?`${r.victory.points} points d’aventure`:r.victory.mode==='turns'?`${r.victory.turns} jours`:'le premier voyage réussi';
 return [
  {id:'journee',name:'Journée',icon:'☀️',category:'jouer',short:ultra?'La course suit une horloge continue.':'Rouler, manger, puis choisir où dormir.',body:ultra?'En Ultra, chaque case, arrêt et sommeil fait avancer l’horloge. Le jour civil ne s’arrête pas quand tu dors ; les barrières horaires restent actives.':'Chaque cycliste dispose d’un nombre limité de cases par journée. Dormir termine la journée et passe au joueur suivant. Une journée sans rouler améliore la récupération nocturne.'},
  {id:'deplacement',name:'Déplacement',icon:'🚴',category:'jouer',short:'Avancer de case voisine en case voisine.',body:ultra?`Trace un trajet de cases voisines puis roule. Chaque case consomme de l’énergie et des heures ; une étape compte au plus ${ULTRA_STEP_MAX} cases entre deux sommeils.`:'Sélectionne les cases entourées sur la carte dans l’ordre, puis confirme le trajet. Tu ne peux pas dépasser ta distance du jour ni dépenser plus d’énergie que tu n’en possèdes.'},
  {id:'hors-route',name:'Hors route',icon:'🛣️',category:'terrain',short:!plateau?'Sans objet en mode Tuiles.':ultra?'Une case plus lente en Ultra.':'Quitter les chemins peut limiter la journée.',body:!plateau?'La règle de route et hors-route concerne le plateau Europe. En mode Tuiles, on suit plutôt les connexions dessinées sur les tuiles posées.':ultra?'En Ultra, rouler hors route ajoute du temps au trajet selon le vélo et le matériel. Le GPS supprime la limite de cases hors route, mais pas le temps supplémentaire.':r.offroad?.enabled?`Sans ${r.equipment[r.offroad.item]?.name||'GPS'}, un pas hors route limite toute la journée : ${Object.entries(r.offroad.maxDistance).map(([bike,n])=>`${r.bikes[bike]?.name||bike} ${n} cases`).join(', ')}. Les cases déjà parcourues comptent aussi. L’équipement adapté supprime cette limite.`:'Les routes ne changent pas la limite de déplacement dans ce profil.'},
  {id:'energie',name:'Énergie',icon:'⚡',category:'vie',short:'La réserve dépensée pour pédaler.',body:`Tu commences avec ${r.startEnergy} énergie et peux en avoir jusqu’à ${r.maxEnergy}, sous réserve de la fatigue. Le coût de base de chaque case dépend de son terrain ; météo, vélo et effets peuvent le modifier. Manger et dormir permettent de récupérer.`},
  {id:'fatigue',name:'Fatigue',icon:'😴',category:'vie',short:'Elle réduit l’énergie maximale disponible.',body:r.fatigue?.enabled?(ultra?'En Ultra, la fatigue vient surtout des heures passées éveillé : la dette de sommeil augmente, réduit l’énergie disponible et finit par provoquer hallucinations puis micro-sommeils.':immersion?'En mode Immersion, la fatigue va de 0 à 5 : chaque niveau bloque 1 point d’énergie maximale. Les journées difficiles et les cols l’augmentent ; une bonne nuit aide à récupérer.':`Chaque niveau de fatigue enlève ${r.fatigue.maxEnergyPenalty} énergie au maximum disponible. Les journées de route et les cols l’augmentent ; une bonne nuit aide à récupérer.`):'La fatigue est désactivée dans ce profil de règles.'},
  {id:'repas',name:'Repas',icon:'🍲',category:'vie',short:'Manger rend de l’énergie.',body:ultra?`En Ultra, seul le repas froid est disponible : +${r.food.coldEnergy??2} énergie de base, faim −2 et 15 minutes d’arrêt. La fatigue peut réduire le gain réel.`:immersion?`Repas froid : +${r.food.coldEnergy??2} énergie de base ; repas chaud avec réchaud : +${r.food.hotEnergy??3}. La fatigue réduit parfois le gain, et le niveau Expédition le divise davantage. On peut manger partout.`:`Repas froid : +${r.food.coldEnergy??2} énergie de base ; repas chaud avec réchaud : +${r.food.hotEnergy??3}. On peut manger partout, jusqu’à ${r.food.maxPerTurn} repas par jour. Certaines cartes bonus améliorent le gain.`},
  {id:'bivouac',name:'Bivouac',icon:'⛺',category:'vie',short:'Dormir dehors, normalement avec une tente.',body:!plateau?`En mode Tuiles, le bivouac occupe ${amount(r.rest.bivouac.days,'jour','jours')}, requiert normalement la tente et rend ${r.cardBalance.bivouacEnergy} énergie de base selon les règles de repos.`:ultra?'En Ultra, choisis une sieste, un cycle, une nuit courte ou une vraie nuit selon ton besoin de sommeil. La nuit courte prend 4 heures.':immersion?'Gratuit avec la tente : +1 énergie de base, sans réduire la fatigue. Sous la pluie ou l’orage, la nuit peut être plus risquée. Dormir termine la journée.':'En mode Original sur le plateau, le bivouac est gratuit avec la tente et rend +1 énergie de base, sans effacer la fatigue. Après une journée sans rouler, cette énergie est doublée.'},
  {id:'camping',name:'Camping et hôtel',icon:'🏕️',category:'vie',short:ultra?'L’hôtel permet une vraie nuit en ville.':'Des nuits payantes pour mieux récupérer.',body:!plateau?`En mode Tuiles, le camping coûte ${amount(r.rest.camping.price,'pièce','pièces')} et rend ${r.rest.camping.energy} énergie ; l’hôtel coûte ${amount(r.rest.hotel.price,'pièce','pièces')}, est réservé aux villes et rend ${r.rest.hotel.energy} énergie. Les durées de repos viennent des règles.`:ultra?'En Ultra, l’hôtel n’est accessible qu’en ville. Il fait avancer l’horloge de 7 heures, restaure l’énergie et remet à zéro la dette de sommeil.':immersion?`Camping : ${r.rest.camping.price} pièce(s), +2 énergie et fatigue −1 de base. Hôtel : ${r.rest.hotel.price} pièce(s), en ville, +3 énergie et fatigue −2 de base. La difficulté et une journée sans rouler peuvent améliorer la récupération.`:`Camping : ${r.rest.camping.price} pièce(s), +2 énergie ; hôtel : ${r.rest.hotel.price} pièce(s), en ville, +3 énergie. Ces nuits effacent la fatigue en mode Original sur le plateau.`},
  terrain('plaine','Plaine','🌾','La plaine est un terrain facile à traverser. Son coût est indiqué dans les règles de la partie.'),
  terrain('cote','Côte','🌊','Une case de littoral. La mer voisine ne se traverse pas à vélo : utilise une liaison de ferry depuis un port.'),
  terrain('moyenne_montagne','Moyenne montagne','⛰️','Un terrain plus exigeant que la plaine, distinct de la haute montagne.'),
  terrain('montagne','Haute montagne','🏔️','La montagne demande davantage d’énergie. Certaines cartes Voyage exigent plusieurs cases de montagne consécutives.'),
  terrain('col','Col mythique','🚩',ultra?`En Ultra, il faut franchir ${ULTRA_RACE.cols} cols mythiques distincts pour pouvoir terminer la course au Cap Nord. Un col prend ${ULTRA_HOURS.col} heures de base, en plus de son coût en énergie.`:`Le premier passage de chaque cycliste sur ce col rapporte +${r.points.col} points d’aventure. Le col compte aussi comme montagne pour les objectifs, y compris les montagnes consécutives. Coût de base : ${r.terrain.col} énergie.${r.adventure.climberBonus?` Après ${r.adventure.climberCols} cols distincts, le bonus Grimpeur donne +${r.adventure.climberBonus} points, une seule fois.`:''}${r.adventure.colFirstBonus?` Le premier cycliste au col reçoit aussi +${r.adventure.colFirstBonus} points de Premier de cordée.`:''}`,ultra?`${ULTRA_RACE.cols} cols obligatoires pour finir la course.`:`Premier passage : +${r.points.col} points d’aventure.`),
  terrain('ville','Ville','🏘️','La ville permet notamment le ravitaillement, le restaurant, les achats de matériel et parfois le départ ou l’arrivée d’un voyage.'),
  {id:'ferry',name:'Ferry',icon:'⛴️',category:'terrain',short:!plateau?'Absent du mode Tuiles.':ultra?`${ULTRA_FERRY_MAX} bateau autorisé en Ultra.`:`Une traversée entre ports pour ${r.ferryPrice} pièces.`,body:!plateau?'Les ferries sont des liaisons spéciales entre ports du plateau Europe. Le mode Tuiles ne propose pas ces traversées.':ultra?`Le ferry relie des ports désignés. En Ultra, ${ULTRA_FERRY_MAX} traversée est autorisée pendant toute la course et elle consomme ${ULTRA_FERRY_HOURS} heures.`:`Le ferry relie deux ports désignés. La traversée coûte ${r.ferryPrice} pièces et termine la journée à l’arrivée.`},
  {id:'equipement',name:'Équipement',icon:'🎒',category:'materiel',short:'Les objets transportés dans les sacoches.',body:'Chaque objet a un prix et occupe des places. La tente, le réchaud, le GPS, le kit et les autres équipements facilitent certaines actions ou protègent contre des incidents.'},
  {id:'voyage',name:'Carte Voyage',icon:'🗺️',category:'voyage',short:ultra?'La course remplace les cartes Voyage.':'Ton trajet et ses objectifs personnels.',body:ultra?'En Ultra, il n’y a pas de succession de cartes Voyage : le parcours est Lisbonne → Cap Nord avec contrôles horaires et cols obligatoires.':'Une carte Voyage indique une ville de départ, une arrivée et des objectifs de terrain ou de villes. Remplis les étapes, puis rejoins l’arrivée pour obtenir les points annoncés sur la carte.'},
  {id:'objectif',name:'Objectif',icon:'🎯',category:'voyage',short:ultra?'Contrôles et cols obligatoires.':'Une condition à remplir pendant le voyage.',body:ultra?`En Ultra, les objectifs sont les contrôles de ${ULTRA_RACE.checkpoints.join(' puis ')} dans l’ordre, ${ULTRA_RACE.cols} cols mythiques et l’arrivée à ${ULTRA_RACE.to} avant la barrière.`:'Une carte Voyage peut demander des villes intermédiaires, certains terrains ou des cases consécutives. La fiche Voyage montre la progression de chacun.'},
  {id:'points',name:'Points d’aventure',icon:'✨',category:'voyage',short:ultra?'L’Ultra se joue au classement, pas aux points.':'Le score obtenu en explorant et en terminant des voyages.',body:ultra?'En Ultra, l’ordre d’arrivée et le respect des contrôles déterminent le résultat. Les points d’aventure des voyages classiques ne décident pas de la victoire.':`Voyages, cols (+${r.points.col} au premier passage par cycliste) et lieux remarquables rapportent des points. Les conditions de fin de partie se choisissent avant le départ.`},
  {id:'cartes',name:'Cartes Événement',icon:'🃏',category:'modes',short:'Des effets positifs, négatifs, météo ou permanents.',body:immersion?'Le mode Immersion et l’Ultra remplacent les cartes Événement par des scènes de voyage et des choix en route.':plateau&&r.encounters?.enabled?'Ce profil utilise des rencontres à la place des cartes Événement.':`Fin de tour : pioche ${r.eventCards.drawPerTurn} cartes et garde-en 1. Une carte positive aide, une négative gêne un adversaire, une climatique modifie un trajet et un bonus permanent reste posé.`},
  {id:'but',name:'But de la partie',icon:'🏁',category:'jouer',short:ultra?'Atteindre le Cap Nord dans les temps.':'Réussir des voyages et gagner des points.',body:ultra?'Passe Zurich puis Saint-Pétersbourg dans l’ordre, franchis 3 cols mythiques et atteins le Cap Nord avant les barrières. Le classement dépend de l’ordre d’arrivée.':'Choisis une carte Voyage, remplis ses objectifs et rejoins sa ville d’arrivée. Les voyages, cols et découvertes donnent des points d’aventure. La condition de fin est fixée avant la partie.'},
  {id:'distance',name:'Distance du jour',icon:'📏',category:'jouer',short:ultra?`Jusqu’à ${ULTRA_STEP_MAX} cases entre deux sommeils.`:`Jusqu’à ${r.distance} cases de référence par jour.`,body:ultra?`En Ultra, une étape peut contenir jusqu’à ${ULTRA_STEP_MAX} cases entre deux sommeils, mais l’énergie, l’heure et les besoins imposent souvent de s’arrêter plus tôt.`:`La limite dépend du vélo et des règles : distance de référence ${r.distance}, puis ajustements du vélo et des effets du jour. La Randonneuse parcourt normalement une case de moins que le Gravel.`},
  {id:'tracer',name:'Tracer une étape',icon:'🗺️',category:'jouer',short:'Choisir les cases dans leur ordre de passage.',body:'Clique une case accessible entourée sur le plateau, puis les suivantes pour préparer ton trajet. Le jeu affiche le coût ; confirme avec « Rouler ». Un ferry se prend séparément, pas dans le tracé normal.'},
  {id:'fiche',name:'Fiche du cycliste',icon:'📋',category:'jouer',short:'Le tableau de bord de ton personnage.',body:'Les onglets Journée, Sacoches, Voyage et Carnet réunissent ressources, actions, équipement, progression et souvenirs de route. WikiBike est accessible en bas de cette fiche, sans quitter la partie.'},
  {id:'tutoriel',name:'Partie guidée',icon:'🧑‍🏫',category:'jouer',short:'Apprendre à jouer pendant un voyage préparé.',body:'« Apprendre à jouer » accompagne un trajet de Budapest à Athènes en cinq jours. Le guide fait pratiquer la carte Voyage, le tracé, les repas, la météo, le hors-route, la fatigue, le repos et les cartes Événement.'},
  {id:'plateau-europe',name:'Plateau Europe',icon:'🌍',category:'jouer',short:'Voyager sur la carte fixe de l’Europe.',body:'Le plateau Europe relie les cases terrestres voisines, les villes et certains ports. Les traits de route, le hors-route, les ferries, les régions météo et les cartes personnalisées appartiennent à ce type de partie.'},
  {id:'mode-tuiles',name:'Mode Tuiles',icon:'🧩',category:'jouer',short:'Construire le paysage au fil du voyage.',body:'Dans le mode Tuiles, on place et oriente des tuiles compatibles pour étendre la carte, puis on avance sur les connexions créées. Les règles propres au plateau Europe, comme les liaisons de ferry et les routes tracées, ne s’y appliquent pas.'},
  {id:'route',name:'Route',icon:'〰️',category:'terrain',short:'Les traits clairs entre certaines cases.',body:!plateau?'En mode Tuiles, les tracés présents sur chaque tuile déterminent les connexions : il faut poser et orienter les tuiles de façon compatible. La limite hors-route du plateau ne s’applique pas.':ultra?'Suivre une route évite la pénalité horaire du hors-route. Le choix du vélo influence aussi le temps passé sur le goudron ou les pistes.':r.offroad?.enabled?'Suivre les traits de route évite la limite journalière du hors-route. Dès que tu quittes la route sans équipement adapté, la distance maximale de toute la journée diminue.':'Les routes indiquent les chemins du plateau. Cette partie ne leur applique pas de limite de déplacement particulière.'},
  {id:'mer',name:'Mer',icon:'🌊',category:'terrain',short:'Une case interdite au vélo.',body:'Les cases de mer ne se traversent pas en pédalant. Pour rejoindre une autre rive, cherche une liaison de ferry entre ports. Une case « Côte » reste une case terrestre accessible.'},
  {id:'train',name:'Train ou car',icon:'🚆',category:'terrain',short:'Rejoindre le départ d’un nouveau voyage.',body:ultra?'Le voyage rapide en train n’est pas disponible en mode Ultra.':`Après un voyage réussi, tu peux rejoindre en train ou en car la ville de départ de la nouvelle carte choisie. Le trajet prend la journée et coûte 2, 3 ou 4 pièces selon la distance (moins de 10, de 10 à 19, ou 20 cases et plus).`},
  {id:'cout-terrain',name:'Coût du terrain',icon:'⚙️',category:'terrain',short:'L’énergie de base nécessaire pour entrer sur une case.',body:`Avec les règles actuelles : plaine ${r.terrain.plaine}, côte ${r.terrain.cote}, moyenne montagne ${r.terrain.moyenne_montagne}, haute montagne ${r.terrain.montagne}, col ${r.terrain.col}, ville ${r.terrain.ville}. Météo, matériel, vélo et effets de cartes peuvent changer le coût final.`},
  {id:'fourbu',name:'Fourbu',icon:'🥱',category:'vie',short:'Le niveau de fatigue le plus élevé.',body:ultra?'En Ultra, une dette de sommeil très élevée réduit fortement tes capacités. Une vraie nuit ou un hôtel remet la dette à zéro.':immersion?'En Immersion, la jauge de fatigue va jusqu’à 5. Chaque niveau bloque 1 point de la barre d’énergie maximale ; les galères deviennent plus probables quand tu es fatigué.':`Dans le mode Original, tu es fourbu au niveau ${r.fatigue.days}. Chaque niveau enlève ${r.fatigue.maxEnergyPenalty} énergie maximale ; une bonne nuit efface la fatigue.`},
  {id:'repos',name:'Journée de repos',icon:'🛌',category:'vie',short:'Une journée sans rouler avant de dormir.',body:ultra?'En Ultra, le repos se mesure en heures : sieste de 20 minutes, cycle de 1 h 30, nuit courte de 4 h ou vraie nuit de 8 h.':`Si tu ne roules pas avant de choisir une nuit, l’énergie rendue par cette nuit est doublée. Dans le mode Immersion, ce repos aide aussi à réduire davantage la fatigue.`},
  {id:'provisions',name:'Provisions',icon:'🥖',category:'vie',short:'Acheter des repas à emporter.',body:ultra?'En Ultra, la supérette fournit des repas quand elle est ouverte ; station-service et épicerie de hameau peuvent dépanner. Acheter prend du temps.':`Dans les règles de base, ${r.food.price} pièce permet d’acheter ${r.food.quantity} repas${r.food.cityOnly?' en ville':''}. Le nombre transportable dépend du vélo et des sacoches.`},
  {id:'restaurant',name:'Restaurant',icon:'🍽️',category:'vie',short:'Récupérer de l’énergie sans vider les sacoches.',body:ultra?'En Ultra, le restaurant a des horaires : 11 h à 22 h. Il faut tenir compte du temps d’arrêt et des fermetures.':`En ville, un repas au restaurant coûte ${r.food.restaurantPrice} pièce(s) et rend ${r.food.restaurantEnergy} énergie. C’est différent du repas pris dans tes sacoches.`},
  {id:'demander',name:'Demander l’hospitalité',icon:'🏡',category:'vie',short:'Une nuit gratuite, mais incertaine.',body:ultra?'Il n’est pas possible de demander l’hospitalité en mode Ultra.':'Le résultat peut être un grand accueil (énergie, repas et point d’aventure), une place dans un jardin ou un refus. En cas de refus, un camping de dernière minute coûte davantage ; sans pièces, tu dors dehors. Les probabilités varient selon la difficulté.'},
  {id:'nuit-dehors',name:'Nuit dehors',icon:'🌙',category:'vie',short:'Le dernier recours après un refus.',body:ultra?'En Ultra, les options de sommeil sont la sieste, le cycle, la nuit courte, la vraie nuit et l’hôtel ; cette nuit de refus n’existe pas.':'Si tu demandes l’hospitalité, essuies un refus et ne peux pas payer un camping de dernière minute, tu passes une nuit dehors. Elle ne rend pas d’énergie et peut accroître la fatigue.'},
  {id:'eau',name:'Eau et gourdes',icon:'💧',category:'vie',short:'Une ressource à gérer en Bêta et en Ultra.',body:ultra?'Remplis tes gourdes en ville ou aux fontaines ; rivière, lac et torrent sont sûrs avec un filtre. La soif augmente à chaque case et, dès son seuil, une gourde est bue automatiquement. Sans eau, la soif peut ralentir et coûter de l’énergie.':immersion&&r.immersion?.beta?'En Bêta, le Gravel a 2 gourdes et la Randonneuse 3 ; une gourde est bue au premier déplacement du jour. Sans eau : −1 énergie et pas de repas chaud. Les villes et fontaines sont sûres ; rivière, lac ou torrent sans filtre présentent 1 risque sur 4 de contamination.':'L’eau n’est pas une ressource à gérer dans ce mode. Le mode Bêta et l’Ultra ajoutent des gourdes, fontaines et points d’eau.'},
  {id:'faim',name:'Faim et soif en Ultra',icon:'🥤',category:'vie',short:'Deux besoins qui augmentent pendant la course.',body:ultra?'Chaque case augmente la faim et la soif. Manger un repas froid réduit la faim ; boire réduit la soif. Une dette trop forte ajoute des heures et retire de l’énergie à chaque case.':'La gestion détaillée de la faim et de la soif appartient au mode Ultra. Dans les autres modes, les repas servent surtout à récupérer de l’énergie.'},
  {id:'villes-intermediaires',name:'Villes intermédiaires',icon:'🏙️',category:'voyage',short:'Des villes traversées entre départ et arrivée.',body:'Certaines cartes Voyage demandent de passer par un nombre de villes. La ville de départ et celle d’arrivée ne comptent pas comme villes intermédiaires. La progression se voit dans l’onglet Voyage.'},
  {id:'consecutives',name:'Cases consécutives',icon:'🔗',category:'voyage',short:'Traverser plusieurs terrains du même type à la suite.',body:'Une carte peut demander des plaines, des côtes ou des montagnes consécutives. Repasser sur une case déjà traversée ne lui donne pas un nouveau point de progression et ne rompt pas forcément la série ; changer de terrain, si.'},
  {id:'col-montagne',name:'Col et objectif montagne',icon:'⛰️',category:'voyage',short:'Un col peut valider une étape montagne.',body:'Pour les objectifs de carte Voyage, un col mythique compte comme une case montagne. Il peut donc faire progresser aussi une série de montagnes consécutives. Son bonus de points de col s’ajoute séparément.'},
  {id:'score-voyage',name:'Points d’une carte Voyage',icon:'💠',category:'voyage',short:'Le minimum et le maximum figurent sur la carte.',body:'Une arrivée avec tous les objectifs remplis donne le maximum annoncé sur la carte ; arriver sans les avoir tous remplis permet de terminer au minimum indiqué. Les cartes les plus difficiles valent davantage.'},
  {id:'arrivee-partielle',name:'Arrivée sans tous les objectifs',icon:'🏁',category:'voyage',short:'Terminer au minimum de points indiqué.',body:'Une fois dans la ville d’arrivée, tu peux choisir « Terminer le voyage ici » même si tous les compteurs ne sont pas remplis. Tu reçois alors les points minimum de la carte, pas son maximum.'},
  {id:'nouveau-voyage',name:'Nouveau voyage',icon:'🧭',category:'voyage',short:'Choisir parmi trois cartes après un voyage réussi.',body:'Dans une partie qui continue après l’arrivée, tu reçois trois nouvelles cartes Voyage au début de ton tour suivant et tu en choisis une. Les objectifs du nouveau voyage ne comptent que les cases parcourues après ce choix.'},
  {id:'lieu-cache',name:'Lieu remarquable « ? »',icon:'❓',category:'voyage',short:!plateau?'Une découverte propre au plateau Europe.':'Une découverte qui rapporte 1 à 3 points.',body:!plateau?'Les jetons de lieux remarquables « ? » sont placés sur le plateau Europe, pas dans le mode Tuiles.':`Sur le plateau Europe, les jetons « ? » sont placés loin des routes. Le premier cycliste qui traverse leur case découvre le lieu et gagne 1, 2 ou 3 points d’aventure.${ultra?' Ce score ne détermine pas le classement Ultra.':''}`},
  {id:'grimpeur',name:'Bonus Grimpeur',icon:'🏅',category:'voyage',short:`${r.adventure.climberCols} cols distincts : +${r.adventure.climberBonus} points.`,body:ultra?'En Ultra, les cols servent de condition obligatoire de la course ; le bonus de points Grimpeur ne détermine pas le classement.':`Quand un cycliste franchit pour la première fois ${r.adventure.climberCols} cols mythiques distincts, il obtient +${r.adventure.climberBonus} points d’aventure une seule fois. Chaque col lui a également donné +${r.points.col} points lors de son premier passage.`},
  {id:'premier-cordee',name:'Premier de cordée',icon:'🚩',category:'voyage',short:r.adventure.colFirstBonus?`Premier cycliste sur un col : +${r.adventure.colFirstBonus} points.`:'Bonus désactivé dans les règles actuelles.',body:r.adventure.colFirstBonus?`Le premier cycliste à atteindre un col mythique encore vierge reçoit +${r.adventure.colFirstBonus} points supplémentaires. Cela ne remplace pas les +${r.points.col} points de son premier passage personnel.`:'Ce bonus optionnel vaut actuellement 0. S’il est activé dans les règles, seul le premier cycliste qui atteint chaque col mythique le reçoit.'},
  {id:'fin-partie',name:'Fin de partie',icon:'🏆',category:'voyage',short:ultra?'Ordre d’arrivée et barrières horaires.':`Condition actuelle : ${victory}.`,body:ultra?`Il faut passer les contrôles dans l’ordre, franchir les ${ULTRA_RACE.cols} cols requis et atteindre ${ULTRA_RACE.to} avant la fin du jour ${ULTRA_RACE.barriers.at(-1)}. Le classement suit l’ordre d’arrivée.`:`La partie se termine à ${victory}. ${r.victory.mode==='multi'&&r.victory.voyages?`Le premier à réussir ${r.victory.voyages} voyages reçoit +${r.victory.voyagesBonus??5} points ; le classement final se fait aux points d’aventure. `:''}Un prêt non remboursé retire aussi des points.`},
  {id:'velos',name:'Choisir son vélo',icon:'🚲',category:'materiel',short:'Distance, place et prix diffèrent.',body:'Le choix du vélo change le budget de départ, la capacité des sacoches et la distance possible. En Ultra, il change aussi le temps de parcours selon la route, les pistes et le poids transporté.'},
  {id:'gravel',name:'Gravel',icon:'🚴',category:'materiel',short:ultra?'Gravel d’ultra : 9,5 kg.':`${r.bikes.gravel.capacity} places de base dans les sacoches.`,body:ultra?'Le Gravel d’ultra est une des trois montures du garage : 9,5 kg, allure constante sur le goudron et +1 heure hors route. Consulte « Gravel d’ultra » pour ses caractéristiques complètes.':`Dans ces règles, le Gravel coûte ${r.bikes.gravel.price} pièce(s), dispose de ${r.bikes.gravel.capacity} places et peut transporter ${r.bikes.gravel.maxFood} repas de base. Il garde la distance de référence du jour, avant les autres effets.`},
  {id:'randonneuse',name:'Randonneuse',icon:'🚲',category:'materiel',short:ultra?'Vélo des modes classiques, absent du garage Ultra.':`${r.bikes.randonneur.capacity} places de base.`,body:ultra?'Le garage Ultra propose Route endurance, Gravel d’ultra et VTT semi-rigide. La Randonneuse et ses pièces appartiennent aux autres modes.':`Dans ces règles, la Randonneuse coûte ${r.bikes.randonneur.price} pièce(s), dispose de ${r.bikes.randonneur.capacity} places et peut transporter ${r.bikes.randonneur.maxFood} repas de base. Son ajustement de distance est de ${r.bikes.randonneur.extraDistance} case(s).`},
  {id:'sacoches',name:'Sacoches',icon:'🧳',category:'materiel',short:ultra?'En Ultra, elles font partie du poids de base.':'Augmenter la place et la capacité de repas.',body:ultra?'Le garage Ultra compte déjà les sacoches dans la charge de base. Le choix du matériel se fait surtout en kilogrammes ; au-delà de certains seuils, les cols et la montagne prennent plus de temps.':`L’équipement Sacoches occupe ${r.equipment.sacoches.space} place(s), mais ajoute ${r.equipment.sacoches.capacityBonus??2} places de capacité et ${r.equipment.sacoches.foodBonus??2} repas transportables. Vérifie la place disponible avant d’acheter un autre objet.`},
  {id:'tente',name:'Tente',icon:'⛺',category:'materiel',short:ultra?'Sommeil Ultra : choix d’heures plutôt que tente.':'Nécessaire pour bivouaquer.',body:ultra?'Le mode Ultra utilise des durées de sommeil et un équipement de garage spécifique, comme le sac de bivouac. La règle de tente obligatoire du bivouac classique ne s’applique pas à ces choix.':`La tente coûte ${r.equipment.tente.price} pièce(s) et occupe ${r.equipment.tente.space} place(s). Sans elle, le bivouac normal est indisponible, sauf effet particulier qui l’autorise gratuitement.`},
  {id:'rechaud',name:'Réchaud',icon:'🔥',category:'materiel',short:ultra?'Pas de repas chaud en Ultra.':'Préparer un repas chaud.',body:ultra?'En mode Ultra, les repas sont froids : le réchaud n’est pas utilisé pour préparer un repas chaud.':`Le réchaud coûte ${r.equipment.rechaud.price} pièce(s) et occupe ${r.equipment.rechaud.space} place(s). Avec lui, un repas chaud rend ${r.food.hotEnergy??3} énergie de base au lieu de ${r.food.coldEnergy??2} pour un repas froid.${immersion&&r.immersion?.beta?' Il faut avoir de l’eau dans une gourde pour cuisiner en mode Bêta.':''}`},
  {id:'gps',name:'GPS',icon:'📍',category:'materiel',short:'Supprimer la limite hors route.',body:ultra?'Dans le garage Ultra, le GPS et sa batterie suppriment la limite de cases hors route, mais pas le temps supplémentaire imposé par le terrain, le vélo et la nuit.':r.offroad?.enabled?`L’objet ${r.equipment[r.offroad.item]?.name||'GPS'} évite la limite de cases imposée dès que tu quittes la route. Dans les règles actuelles, il coûte ${r.equipment[r.offroad.item]?.price??0} pièce(s).`:'La limite hors route est désactivée dans ce profil ; le GPS n’est donc pas nécessaire pour la contourner.'},
  {id:'chambre',name:'Chambre à air',icon:'🛞',category:'materiel',short:'Se préparer à une crevaison.',body:'La chambre à air permet de répondre à certaines crevaisons ou cartes négatives. Selon l’incident, elle peut être consommée après usage ; le kit de réparation est un autre moyen de se protéger.'},
  {id:'kit',name:'Kit de réparation',icon:'🔧',category:'materiel',short:'Réparer le vélo lors de certains incidents.',body:`Le kit coûte ${r.equipment.kit.price} pièce(s) et occupe ${r.equipment.kit.space} place(s). Il donne une option de réparation lors de scènes ou cartes adaptées, ce qui peut éviter une pénalité d’énergie ou un retour forcé.`},
  {id:'secours',name:'Trousse de secours',icon:'🩹',category:'materiel',short:'Réduire les conséquences de certaines chutes.',body:'La trousse de secours protège dans les incidents de blessure qui la mentionnent. Elle ne rend pas automatiquement de l’énergie : son usage dépend de la carte ou de la scène en cours.'},
  {id:'duvet',name:'Matelas et duvet',icon:'🛏️',category:'materiel',short:'Une meilleure nuit dans le mode Original.',body:ultra?'En Ultra, le garage propose plutôt un sac de bivouac (+2 énergie après une nuit courte) ou une couverture de survie (+1 après un cycle).':immersion?'Le matelas et duvet ne donne pas le bonus d’énergie du mode Original pendant les nuits Immersion ; les effets de la nuit sont indiqués dans le choix du couchage.':'En mode Original, cet équipement ajoute 1 énergie à la récupération nocturne. Il occupe de la place dans les sacoches.'},
  {id:'filtre',name:'Filtre à eau',icon:'💧',category:'materiel',short:'Sécuriser l’eau des rivières et torrents.',body:immersion&&r.immersion?.beta||ultra?'Avec le filtre, le remplissage des gourdes à une rivière, un lac ou un torrent devient sûr. Sans lui, l’eau peut être contaminée et provoquer une perte d’énergie et un gain de fatigue.':'Le filtre est surtout utile en Bêta et en Ultra, où l’eau est une ressource à gérer.'},
  {id:'marche',name:'Marché et achats',icon:'🛒',category:'materiel',short:'Acheter du matériel et du ravitaillement.',body:ultra?'Les achats d’Ultra dépendent des horaires et font avancer l’horloge. Le poids du matériel remplace la gestion habituelle des pièces.':'Le matériel s’achète en ville si tu as assez de pièces et de place. Les provisions et le restaurant sont d’autres moyens de te ravitailler. Les prix et capacités suivent les règles choisies.'},
  {id:'banque',name:'Banque et prêt',icon:'🏦',category:'materiel',short:`Emprunter ${r.loan?.amount??5} pièces, puis rembourser.`,body:ultra?'En Ultra, l’argent et le prêt bancaire ne font pas partie de la course.':`En ville, ou pendant le choix du train, tu peux emprunter ${r.loan?.amount??5} pièces sans intérêts si tu n’as pas déjà un prêt. Le remboursement se fait en une fois dans une banque. Si le prêt reste dû à la fin : −${r.loan?.penalty??3} points d’aventure.`},
  {id:'budget',name:'Budget de voyage',icon:'🪙',category:'materiel',short:ultra?'L’Ultra ne compte pas les pièces.':`+${r.budget.amount} pièces tous les ${r.budget.every} tours.`,body:ultra?'En Ultra, on ne compte pas les pièces : le matériel pèse et les arrêts coûtent du temps.':`Après l’achat du vélo et du matériel, le budget ajoute ${r.budget.startBonus} pièces. Ensuite, ${r.budget.amount} pièces sont versées tous les ${r.budget.every} tours selon les règles de la partie. La difficulté Immersion peut ajuster les pièces de départ.`},
  {id:'original',name:'Mode Original',icon:'🎲',category:'modes',short:'Voyages, cartes Événement et nuits.',body:'Le mode Original suit les objectifs des cartes Voyage et les points d’aventure. Les cartes positives, négatives, climatiques et permanentes donnent des choix tactiques ; selon les options, un bulletin météo ou des rencontres remplacent certaines cartes.'},
  {id:'immersion',name:'Mode Immersion',icon:'🧭',category:'modes',short:'Des scènes vécues plutôt que des cartes.',body:'En Immersion, les événements dépendent de la zone, du terrain, de la météo et de la fatigue. Les choix en route et les nuits racontent le voyage ; certaines situations restent visibles plusieurs jours sur la carte. La fatigue se compte sur 5 niveaux.'},
  {id:'difficulte',name:'Difficulté Immersion',icon:'🧗',category:'modes',short:'Balade, Voyage, Aventure ou Expédition.',body:ultra?'En Ultra, la difficulté Immersion est fixée sur Voyage ; la course a ses propres contrôles, heures et règles de survie.':`Le niveau choisi agit notamment sur l’énergie et les pièces de départ, les galères, les paris, le refus d’hospitalité et la durée limite.${immersion?` Niveau de cette partie : ${LEVELS[r.immersion?.level]?.name||'Voyage'}.`:' Ces niveaux ne s’appliquent pas au mode Original ni aux Tuiles.'} En Expédition, les probabilités peuvent être cachées et les repas moins efficaces.`},
  {id:'scenes',name:'Scène en route',icon:'🎭',category:'modes',short:'Un choix raconté au moment où il arrive.',body:'En Immersion, une situation peut surgir sur une case : rencontre, galère ou belle surprise. Lis les choix avant de répondre ; certains consomment un objet, une pièce, un repas, de l’énergie ou changent la journée suivante.'},
  {id:'pari',name:'Pari',icon:'🎲',category:'modes',short:'Une issue incertaine annoncée avant le choix.',body:'Certains choix montrent une probabilité de réussite : tu connais le risque, pas le résultat. La fatigue et le niveau de difficulté peuvent modifier les chances. En Expédition, certaines probabilités ne sont pas affichées.'},
  {id:'situation',name:'Imprévu durable',icon:'⚠️',category:'modes',short:'Une zone de la carte affectée plusieurs jours.',body:'Dans le mode Immersion, une situation locale peut apparaître sur plusieurs cases pendant quelques jours : feu de forêt, fête, col fermé ou autre événement. Elle peut ralentir, bloquer ou modifier un passage ; la zone hachurée l’indique sur la carte.'},
  {id:'compagnon',name:'Compagnon de route',icon:'🤝',category:'modes',short:'Un voyageur susceptible de revenir plus tard.',body:'Certaines belles rencontres en Immersion donnent un compagnon. Des retrouvailles peuvent arriver quelques jours plus tard ; rouler ensemble pendant trois jours fait monter la fatigue moins vite.'},
  {id:'rencontres',name:'Option Rencontres',icon:'💬',category:'modes',short:'Un choix le soir à la place des cartes.',body:'Si l’option Rencontres est activée, chaque fin de tour peut proposer une rencontre liée à l’endroit où tu t’arrêtes. Tu choisis une réponse et ses effets sur les ressources, les points ou le lendemain.'},
  {id:'positive',name:'Carte positive',icon:'🟩',category:'modes',short:'Un avantage joué pour toi.',body:'Dans le mode à cartes, les positives se jouent pendant ton tour et peuvent améliorer le trajet ou les ressources. La main et le nombre de cartes jouables suivent les règles de la partie.'},
  {id:'negative',name:'Carte négative',icon:'🟥',category:'modes',short:'Une difficulté posée sur un adversaire.',body:'Une carte négative jouée contre un autre cycliste est révélée et résolue au début de son tour. Selon la carte, du matériel ou un choix peut éviter la pénalité ; « Coup de pouce » peut annuler une attaque.'},
  {id:'climatique',name:'Carte climatique',icon:'🌦️',category:'modes',short:'Une météo imposée au trajet d’un autre.',body:'Dans le jeu à cartes sans météo annoncée, les cartes climatiques peuvent être jouées lorsque l’autre cycliste annonce son trajet. L’option Bulletin météo les retire de la pioche.'},
  {id:'permanent',name:'Bonus permanent',icon:'🟨',category:'modes',short:`Au plus ${r.eventCards.bonusLimit} bonus posés.`,body:`Les bonus permanents restent équipés devant le cycliste et donnent des effets durables. Le profil actuel permet d’en poser ${r.eventCards.bonusLimit} ; si la place est pleine, il faut choisir quoi remplacer.`},
  {id:'meteo',name:'Météo annoncée',icon:'🌤️',category:'modes',short:'Un bulletin pour les régions du plateau.',body:!plateau?'Le bulletin météo régional est une option du plateau Europe. En mode Tuiles, la météo peut venir des cartes climatiques, mais il n’y a pas de bulletin régional du plateau.':r.immersion?.level==='expedition'&&immersion?'En Expédition, le bulletin montre seulement la météo du jour : celle de demain reste cachée. Les cinq régions du plateau sont Ouest, Alpes, Nord, Est et Balkans.':`Quand l’option est active, le bulletin donne le temps du lendemain pour cinq régions : Ouest, Alpes, Nord, Est et Balkans. La région d’une case dépend de sa ville repère la plus proche. Les cartes climatiques sont alors retirées.`},
  {id:'temps',name:'Effets de la météo',icon:'⛈️',category:'modes',short:'Vent, pluie, orage, neige ou beau temps.',body:'Le vent de face ajoute 1 énergie à la première case du jour ; la pluie ajoute 1 énergie hors route ; l’orage limite à 3 cases ; la neige ajoute 1 énergie en montagne et sur les cols. Le beau temps n’ajoute rien. Ces effets concernent la météo annoncée du plateau.'},
  {id:'beta',name:'Mode Bêta',icon:'🧪',category:'modes',short:'Immersion avec eau et règles expérimentales.',body:'Le mode Bêta ajoute notamment les gourdes, les fontaines, le filtre à eau et un calendrier aux scènes d’Immersion. Le contenu est à l’essai : il peut différer des règles du mode Original ou du niveau Voyage standard.'},
  {id:'beta-calendrier',name:'Calendrier Bêta',icon:'📅',category:'modes',short:'Les boutiques suivent les jours et les fêtes.',body:'La partie commence un lundi. Dans de nombreux pays, supérette et magasin de vélo sont fermés le dimanche ; en France, le magasin de vélo peut aussi fermer le lundi. Une fête locale peut fermer les boutiques mais rapporter +1 point d’aventure lors du passage en ville.'},
  {id:'beta-eau-contaminee',name:'Eau contaminée',icon:'🤢',category:'modes',short:'Un risque sans filtre aux points d’eau naturels.',body:'En Bêta, remplir les gourdes à la rivière, au lac ou au torrent sans filtre a 1 chance sur 4 de provoquer une contamination : −2 énergie et +1 fatigue. En ville et à la fontaine d’un hameau, l’eau est sûre.'},
  {id:'ultra',name:'Mode Ultra',icon:'⏱️',category:'modes',short:'Une course d’endurance en temps continu.',body:`De ${ULTRA_RACE.from} à ${ULTRA_RACE.to}, l’Ultra suit une horloge qui ne s’arrête jamais. Il faut gérer sommeil, faim, soif, équipement et poids, passer ${ULTRA_RACE.checkpoints.length} contrôles dans l’ordre et franchir ${ULTRA_RACE.cols} cols mythiques. Le classement dépend de l’arrivée, pas des points de voyage.`},
  {id:'ultra-controles',name:'Contrôles Ultra',icon:'🛂',category:'modes',short:`${ULTRA_RACE.checkpoints.join(', ')}, puis ${ULTRA_RACE.to}.`,body:`Passe ${ULTRA_RACE.checkpoints.map((city,i)=>`${city} avant la fin du jour ${ULTRA_RACE.barriers[i]}`).join(', puis ')}. L’arrivée à ${ULTRA_RACE.to} est limitée à la fin du jour ${ULTRA_RACE.barriers.at(-1)} et exige ${ULTRA_RACE.cols} cols mythiques franchis. Rater une barrière élimine de la course.`},
  {id:'ultra-sommeil',name:'Sommeil en Ultra',icon:'💤',category:'modes',short:'Sieste, cycle, nuit courte, vraie nuit ou hôtel.',body:`Tu choisis quand dormir : ${ULTRA_SLEEP.map(s=>`${s.name.toLowerCase()} ${s.hours<1?Math.round(s.hours*60)+' min':String(s.hours).replace('.',',')+' h'}`).join(', ')}. Chaque choix fait avancer l’horloge et réduit différemment la dette de sommeil. La vraie nuit et l’hôtel remettent la dette à zéro.`},
  {id:'ultra-poids',name:'Poids en Ultra',icon:'⚖️',category:'modes',short:'Le matériel lourd ralentit les ascensions.',body:`Le poids remplace le budget en pièces. À partir de ${ULTRA_WEIGHT.light} kg, les cols coûtent 1 heure supplémentaire ; à partir de ${ULTRA_WEIGHT.heavy} kg, la haute montagne aussi. Le garage Ultra affiche le poids total avant le départ.`},
  {id:'ultra-chrono',name:'Heures par terrain en Ultra',icon:'⌛',category:'modes',short:'Une case prend du temps, même si elle est facile.',body:`Coûts de base : ville ${ULTRA_HOURS.ville} h, plaine et côte ${ULTRA_HOURS.plaine} h, moyenne montagne ${ULTRA_HOURS.moyenne_montagne} h, haute montagne ${ULTRA_HOURS.montagne} h, col mythique ${ULTRA_HOURS.col} h. Nuit, hors-route, vélo, fatigue, poids et équipement modifient ces durées.`},
  {id:'ultra-rivaux',name:'Rivaux en Ultra',icon:'🚴',category:'modes',short:`${ULTRA_RIVALS.length} coureurs sur le même parcours.`,body:`Les ${ULTRA_RIVALS.length} autres coureurs progressent en même temps que toi. Le classement, les contrôles, les abandons et les arrivées se mettent à jour avec l’horloge. Le journal du matin résume les nouvelles de la course.`},
  {id:'sauvegarde',name:'Sauvegarder',icon:'💾',category:'outils',short:'Conserver la partie en cours.',body:'Le menu Sauvegarde se trouve en bas de la fiche. « Sauvegarder maintenant » enregistre l’état de la partie sur cet appareil. Une sauvegarde locale reste liée au navigateur utilisé.'},
  {id:'autosave',name:'Sauvegarde automatique',icon:'🔄',category:'outils',short:'Activer ou couper l’enregistrement automatique.',body:'Le sous-menu Sauvegarde indique si l’enregistrement automatique est activé. Il permet de changer ce réglage sans quitter la partie ; une sauvegarde manuelle reste possible.'},
  {id:'exporter',name:'Exporter une partie',icon:'⬇️',category:'outils',short:'Garder un fichier de sa partie.',body:'Le sous-menu Sauvegarde propose l’export. Le fichier permet de conserver une copie de la partie en dehors du stockage local du navigateur, par exemple avant de changer d’appareil.'},
  {id:'journal',name:'Journal et carnet',icon:'📖',category:'outils',short:'Retrouver les événements de la route.',body:'Le Carnet de la fiche raconte les journées ; le Journal de route et les statistiques récapitulent les déplacements, cols, découvertes et points. Ils permettent de comprendre comment la partie a évolué.'},
  {id:'regles',name:'Règles détaillées',icon:'📚',category:'outils',short:'Les explications complètes de chaque action.',body:'Le bouton « Règles » du jeu ouvre les chapitres Se déplacer, Manger & dormir, Voyages & points, Cartes, Météo et Fin de partie. WikiBike sert d’accès rapide aux définitions ; les règles détaillées expliquent les procédures.'},
  {id:'editeur',name:'Éditeur de carte',icon:'🧱',category:'outils',short:'Personnaliser le plateau Europe.',body:'L’éditeur permet de changer des terrains et l’effort des cols, puis d’enregistrer ou d’exporter une carte. Les villes nécessaires aux voyages et aux ferries restent protégées pour conserver un plateau jouable.'},
  {id:'en-ligne',name:'Partie en ligne',icon:'🌐',category:'outils',short:'Jouer à plusieurs sur le plateau.',body:'Chaque joueur joue à son tour. Les actions qui changent la partie attendent ton tour ; la fiche, le journal, la météo et WikiBike restent consultables pour lire les règles et suivre la partie.'},
  ...voyages.map(v=>{const [minimum,maximum]=VOYAGE_POINTS[v.id];return {id:`carte-${v.id}`,name:v.title,icon:'🗺️',category:'catalogue',short:`${v.from} → ${v.to} · ${minimum} à ${maximum} points`,body:`Départ : ${v.from}. Arrivée : ${v.to}. Objectifs : ${voyageObjectives(v)}. Tous les objectifs remplis : +${maximum} points d’aventure. Arrivée sans tous les objectifs : +${minimum} points. Seules les cases parcourues pour ce voyage comptent.`};}),
  ...Object.entries(ULTRA_BIKES).map(([id,b])=>({id:`ultra-velo-${id}`,name:b.name,icon:'🚲',category:'garage-ultra',short:`${b.kg} kg · ${b.tag}.`,body:`Vélo du garage Ultra. ${b.line} Son poids de base est de ${b.kg} kg, avant les sacoches, les provisions et le matériel.`})),
  ...Object.entries(ULTRA_GEAR).map(([id,g])=>({id:`ultra-matos-${id}`,name:g.name,icon:'🎒',category:'garage-ultra',short:`${g.kg} kg de matériel Ultra.`,body:`Équipement du garage Ultra : ${g.text} Il ajoute ${g.kg} kg au chargement.${g.not?.length?` Incompatible avec : ${g.not.map(b=>ULTRA_BIKES[b].name).join(', ')}.`:''}`})),
 ];
}
